function library(){const h=$('#blocks'),q=$('#search').value.toLowerCase();h.replaceChildren();for(const group of new Set(Object.values(catalog).map(t=>t.group))){const list=Object.entries(catalog).filter(([id,t])=>t.group===group&&(t.name+' '+t.description+' '+id).toLowerCase().includes(q));if(!list.length)continue;const details=E('details','','toolbox-group');details.open=!!q||S.groups.has(group);const summary=E('summary',group);summary.append(E('span',String(list.length),'count'));details.append(summary);details.ontoggle=()=>{if(!q)details.open?S.groups.add(group):S.groups.delete(group);};for(const [type,t]of list){const b=B('',()=>{S.preview=newNode(type);S.selected=null;S.edge=null;S.tab='config';canvas();inspector();layout();},'library-item');b.draggable=true;b.dataset.type=type;b.ondragstart=e=>e.dataTransfer.setData('application/th-node',type);const text=E('span');text.append(E('strong',t.name),E('small',t.description));b.append(blockIcon(type),text,E('span','◇','add-symbol'));details.append(b);}h.append(details);}$('#count').textContent=Object.keys(catalog).length;}

