function canvas(){const h=$('#nodes');h.replaceChildren();for(const n of S.graph.nodes){const t=catalog[n.type];if(!t)continue;const card=E('article','','node '+t.color+' '+nodeStatus(n)+(S.selected===n.id?' selected':'')+(n.type==='note'?' sticky':''));card.dataset.id=n.id;card.style.left=n.x+'px';card.style.top=n.y+'px';const head=E('div','','node-head');head.append(blockIcon(n.type),E('strong',n.name));card.append(head);head.onpointerdown=e=>dragNode(e,n);if(n.type==='note')card.append(E('p',n.config.text,'sticky-text'));else{card.append(E('p',n.type==='model'?n.config.model:t.group,'node-description'));const foot=E('div','','node-status'),r=S.run?.trace?.filter(t=>t.nodeId===n.id).at(-1);foot.append(E('span','','status-dot'),E('span',statusNames[nodeStatus(n)]));if(r?.duration!==undefined)foot.append(E('small',(r.duration/1000).toFixed(2)+'s'));card.append(foot);}for(const side of ['inputs','outputs'])for(const [key,type]of Object.entries(t[side])){const p=port(n,side,key),dot=B('',e=>{e.stopPropagation();link(n,side,key);},'port '+side+' '+type,(side==='inputs'?'Input ':'Output ')+key+' · '+type);dot.setAttribute('aria-label',n.name+' '+side+' '+key);dot.dataset.port=key;dot.dataset.side=side;dot.style.left=p.x-n.x-9+'px';dot.style.top=p.y-n.y-9+'px';if(S.graph.edges.some(e=>side==='inputs'?e.target===n.id&&e.targetPort===key:e.source===n.id&&e.sourcePort===key))dot.classList.add('connected');card.append(dot);if(side==='inputs'&&key!=='in'){const label=E('span',key,'port-label');label.style.left=p.x-n.x+'px';card.append(label);}}card.onclick=e=>{e.stopPropagation();S.selected=n.id;S.preview=null;S.edge=null;canvas();inspector();layout();};card.ondblclick=e=>{if(e.target.closest('.port'))return;const c=$('#canvas');S.view={scale:1,x:c.clientWidth/2-n.x-110,y:c.clientHeight/2-n.y-50};transform();};h.append(card);}$('#summary').textContent=S.graph.nodes.length+' blocks · '+S.graph.edges.length+' connections';transform();edges();}
const svg=(tag,attrs={})=>{const n=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,v);return n;};
function curve(a,b,type){const gap=Math.max(60,Math.min(160,Math.abs(a.x-b.x)/2));return type==='flow'?'M '+a.x+' '+a.y+' C '+(a.x+gap)+' '+a.y+' '+(b.x-gap)+' '+b.y+' '+b.x+' '+b.y:'M '+a.x+' '+a.y+' C '+a.x+' '+(a.y-100)+' '+b.x+' '+(b.y+100)+' '+b.x+' '+b.y;}
function edges(){const h=$('#edges');h.replaceChildren();for(const e of S.graph.edges){const a=S.graph.nodes.find(n=>n.id===e.source),b=S.graph.nodes.find(n=>n.id===e.target);if(!a||!b)continue;const type=catalog[a.type]?.outputs[e.sourcePort];if(!type)continue;const d=curve(port(a,'outputs',e.sourcePort),port(b,'inputs',e.targetPort),type),g=svg('g',{'data-edge':e.id}),hit=svg('path',{d,class:'edge-hit'});hit.onclick=ev=>{ev.stopPropagation();S.edge=e.id;S.selected=null;S.preview=null;edges();inspector();layout();};const source=(!S.runStale?S.run?.trace:[])?.filter(t=>t.nodeId===a.id).at(-1),target=(!S.runStale?S.run?.trace:[])?.filter(t=>t.nodeId===b.id).at(-1),used=type==='flow'?source?.outputPort===e.sourcePort&&!!target:source?.parentNodeId===b.id,active=type==='flow'?used&&source?.status==='success'&&target?.status==='running':used&&source?.status==='running';g.append(hit,svg('path',{d,class:'edge '+type+(S.edge===e.id?' selected':'')+(used&&source?.status==='success'?' completed':'')+(active?' active':'')}));const title=svg('title');title.textContent=a.name+' → '+b.name+' · '+type;g.append(title);h.append(g);}if(S.link){const n=S.graph.nodes.find(n=>n.id===S.link.node);h.append(svg('path',{d:curve(port(n,S.link.side,S.link.key),S.mouse,catalog[n.type][S.link.side][S.link.key]),class:'edge draft'}));}}
function link(n,side,key){if(!editable())return;if(!S.link||S.link.side===side){S.link={node:n.id,side,key};toast('Select a compatible '+(side==='outputs'?'input port':'output port')+' to connect.');return;}const start=S.link,e={id:uid(),source:side==='inputs'?start.node:n.id,sourcePort:side==='inputs'?start.key:key,target:side==='inputs'?n.id:start.node,targetPort:side==='inputs'?key:start.key};const error=connectError(S.graph,e);S.link=null;if(error){toast(error,true);edges();return;}checkpoint();S.graph.edges.push(e);dirty();render();}
