let edgeFrame;function requestEdges(){if(!edgeFrame)edgeFrame=requestAnimationFrame(()=>{edgeFrame=null;edges();});}
function dragNode(e,n){if(e.button!==0||!editable())return;S.preview=null;e.preventDefault();e.stopPropagation();const start=point(e),old={x:n.x,y:n.y};let moved=false;const move=e=>{const p=point(e);if(!moved&&Math.abs(p.x-start.x)+Math.abs(p.y-start.y)>3){checkpoint();moved=true;}if(!moved)return;n.x=Math.max(-15000,Math.min(15000,Math.round((old.x+p.x-start.x)/10)*10));n.y=Math.max(-15000,Math.min(15000,Math.round((old.y+p.y-start.y)/10)*10));const card=$('#nodes [data-id="'+n.id+'"]');card.style.left=n.x+'px';card.style.top=n.y+'px';requestEdges();};window.addEventListener('pointermove',move);window.addEventListener('pointerup',()=>{window.removeEventListener('pointermove',move);if(moved)dirty();S.selected=n.id;S.edge=null;render();},{once:true});}
const c=$('#canvas');c.onpointermove=e=>{S.mouse=point(e);if(S.link)edges();};c.onpointerdown=e=>{if(e.target.closest('.node,#zoom,#minimap')||e.target.classList?.contains('edge-hit'))return;const start={x:e.clientX,y:e.clientY,tx:S.view.x,ty:S.view.y};let moved=false;const move=e=>{moved=true;S.view.x=start.tx+e.clientX-start.x;S.view.y=start.ty+e.clientY-start.y;transform();};window.addEventListener('pointermove',move);window.addEventListener('pointerup',()=>{window.removeEventListener('pointermove',move);if(!moved){S.selected=null;S.preview=null;S.edge=null;S.link=null;render();}},{once:true});};
c.onwheel=e=>{e.preventDefault();const p=point(e),r=c.getBoundingClientRect(),scale=Math.max(.25,Math.min(1.8,S.view.scale*(e.deltaY<0?1.08:.925)));S.view={scale,x:e.clientX-r.left-p.x*scale,y:e.clientY-r.top-p.y*scale};transform();};c.ondragover=e=>e.preventDefault();c.ondrop=e=>{e.preventDefault();const type=e.dataTransfer.getData('application/th-node'),p=point(e);if(catalog[type])add(type,p.x-110,p.y-40);};
function bounds(){if(!S.graph.nodes.length)return {x:0,y:0,w:1000,h:700};const x=Math.min(...S.graph.nodes.map(n=>n.x))-60,y=Math.min(...S.graph.nodes.map(n=>n.y))-60;return {x,y,w:Math.max(...S.graph.nodes.map(n=>n.x))+280-x,h:Math.max(...S.graph.nodes.map(n=>n.y))+180-y};}
