async function runWorkflow(){if(!S.owner)return previewWorkflow();const issues=validateGraph(S.graph,{execution:true,credentials:S.credentials});if(issues.length)return showIssues(issues);if(S.dirty||!S.revision)if(!await save())return;let input={text:S.chat};try{const timer=S.graph.nodes.find(n=>n.type==='timer');if(timer&&!S.chat.trim())input=JSON.parse(timer.config.payload||'{}');if(/^\s*[\[{]/.test(S.chat))input=JSON.parse(S.chat);}catch{return toast('Input JSON is invalid.',true);}try{const r=await api('workflows/'+S.id+'/runs',{method:'POST',body:J({input,sessionId:S.sessionId||(S.sessionId=uid()),allowWrites:S.allowWrites,allowPaid:S.allowPaid})});S.run={...r,trace:[]};S.runStale=false;S.running=true;header();consolePanel();poll(r.id);}catch(e){toast(e.message,true);}}
