function help(){dialog('Build your own workflow',h=>{for(const [title,text]of [['01 · Canvas','Drag blocks from the library and move their headers to arrange them. Drag the background to pan; scroll to zoom.'],['02 · Connections','Connect compatible ports. Models, memory and tools use dedicated agent ports.'],['03 · Function','Use input and return JSON. Test in a network-blocked Web Worker; execute in an isolated container.'],['04 · Observe','Connections animate during real processing. Select a block or trace entry to inspect input, output, status and timing.'],['05 · Add-ins & Timer','Install a connector, configure credentials and test access. Timers run on TH-Server. Cloud providers may charge your account.']])h.append(E('h3',title),E('p',text,'muted'));});}
