$('#import').onchange=async e=>{const f=e.target.files[0];if(!f||!editable())return;try{if(f.size>450000)throw Error('The file exceeds 450 KB.');const v=JSON.parse(await f.text()),g=v.graph||v,issues=validateGraph(g);if(issues.length)throw Error(issues.join('\n'));if(!discard())return;checkpoint();Object.assign(S,{graph:g,title:String(v.title||'Imported workflow').slice(0,120),id:uid(),revision:0,active:false,selected:null});dirty();render();fit();}catch(error){toast(error.message,true);}e.target.value='';};
