async function init(){try{const owner=await api('auth/session');if(!owner.authenticated){try{const draft=JSON.parse(localStorage.getItem('th_studio_draft')||'null');if(draft&&!validateGraph(draft.graph).length){S.graph=draft.graph;S.title=draft.title;S.localSaved=true;render();fit();}}catch{}return;}S.owner=owner;S.addins=(await api('studio/addins')).addins;for(const m of S.addins)registerAddin(m);S.credentials=await api('studio/credentials');const list=(await api('workflows')).workflows;if(list.length){const row=await api('workflows/'+list[0].id);Object.assign(S,{graph:row.graph,title:row.title,id:row.id,revision:row.revision,active:row.active,dirty:false});}library();render();fit();if(new URLSearchParams(location.search).has('connected')){toast('Google service access granted.');window.history.replaceState(null,'','/');}}catch{toast('Design mode. Sign in to save and connect services.');}}
