function externalLink(host,text,url){const a=E('a',text,'guide-link');a.href=url;a.target='_blank';a.rel='noopener noreferrer';host.append(a);}
function blockGuide(host,n){const t=catalog[n.type],guide=serviceGuide(n.type),details=E('details','','block-guide');details.append(E('summary','Connection & usage guide'));if(guide){const p=credentialProviders[serviceBlocks[n.type].provider];details.append(E('p',p.name),E('p',p.cost,'cost-note'));const ol=E('ol');for(const step of p.steps)ol.append(E('li',step));details.append(ol);const spec=serviceBlocks[n.type],scope=spec.googleService?googleScopes[spec.googleService]:spec.msService?microsoftScopes[spec.msService]:spec.provider==='slack'?(spec.effect==='read'?'channels:read (public channels)':'chat:write; invite the bot to the destination channel'):spec.provider==='jira'?(spec.effect==='read'?'read:jira-work':'write:jira-work'):null;if(scope)details.append(E('p','Required permission: '+scope,'origin-label'));for(const step of guide.usage)details.append(E('p',step));externalLink(details,'Official setup documentation ↗',p.docs);}else if(t.effect==='generate-media'){for(const line of credentialProviders.replicate.steps)details.append(E('p',line));externalLink(details,'Model library & pricing ↗','https://replicate.com/explore');}else{const guides={chat:'Provide text or JSON in Chat & test. This trigger starts a manual execution.',timer:'Set an interval of at least five minutes, valid JSON payload and enable the schedule. Paid usage and external writes need separate scheduled approval.',function:'Write JavaScript using input and return a JSON-compatible value. Use Test function with sample JSON before running. Network, filesystem and credentials are unavailable.',model:'Create a provider API key, save it in Connections and choose a model available to your account. Connect the model output to an agent model port. API usage may cost money.',memory:'Connect to an agent memory port. Previous successful conversation turns are retrieved from the same workflow and session.',condition:'Choose a field path and comparison. Connect both Yes and No output ports to the intended next steps.',stats:'Pass an array or an object with rows/data. Choose a numeric field path; missing or invalid values are excluded from numeric statistics.',report:'Pass structured input. Choose Markdown or JSON and connect the result to Output.',database:'Create a read-only PostgreSQL user, configure its connection URL, then use SELECT or WITH. Results are limited to 200 rows and queries to five seconds.',sheets:'Connect Google with Sheets access, enter a spreadsheet ID and tab name. This app appends rows only after write approval.',perplexity:'Create a Perplexity API key and select a supported Sonar model. Search queries may incur API charges.',set:'Enter a JSON object. Its fields are merged into the incoming object.',output:'Connect the final executed branch here. The run returns this block’s actual input.',note:'Add operational notes. Notes do not execute or connect to data ports.',think:'Attach to an agent tool port. Stores a bounded reasoning note without accessing an external service.'};details.append(E('p',guides[n.type]||'Connect a Chat Model, optional Memory and permitted Tools. Set the role and assignment, inspect Connections, validate the workflow and approve any provider charges before running. The role limits which connected tools can run.'));if(n.type.startsWith('addon_'))details.append(E('p','Install a manifest with an HTTPS origin, request path, method and authentication type. Save the matching credential, test a read endpoint, map payload fields with {{input.field}}, and approve POST writes. Changing the origin requires a new token.'));if(n.type==='model'){externalLink(details,'Gemini API keys ↗','https://aistudio.google.com/apikey');externalLink(details,'OpenAI API keys ↗','https://platform.openai.com/api-keys');externalLink(details,'Anthropic API keys ↗','https://console.anthropic.com/settings/keys');}}host.append(details);}
function credentials(selected='gemini'){dialog('Connections & credentials',h=>{h.append(E('p','Credentials are encrypted separately and never included in workflow exports. Enter a secret only when replacing it.','muted'));const selector=E('select'),ids={gemini:'Google Gemini',openai:'OpenAI',anthropic:'Anthropic Claude',perplexity:'Perplexity',postgres:'PostgreSQL',...Object.fromEntries(Object.entries(credentialProviders).map(([id,p])=>[id,p.name])),...Object.fromEntries(S.addins.filter(m=>m.auth!=='none').map(m=>['addon_'+m.id,m.name]))};for(const [id,name]of Object.entries(ids)){const o=E('option',name);o.value=id;selector.append(o);}selector.value=selected==='googleConnected'?'google':selected==='microsoftConnected'?'microsoft':selected;const panel=E('div');h.append(selector,panel);selector.onchange=draw;draw();function draw(){const id=selector.value,p=credentialProviders[id],values={};panel.replaceChildren();panel.append(E('p',S.credentials[id]?'Configured · test or reconnect to verify current access.':'Setup required','credential-status'));if(p){panel.append(E('p',p.cost,'cost-note'));const ol=E('ol','','setup-steps');for(const step of p.steps)ol.append(E('li',step));panel.append(ol);externalLink(panel,'How to get credentials ↗',p.docs);}const fields=id==='google'?[{key:'clientId',label:'OAuth client ID'},{key:'clientSecret',label:'OAuth client secret',secret:true}]:p?.fields||[{key:id==='postgres'?'connectionString':'key',label:id==='postgres'?'Read-only PostgreSQL connection URL':'API key / access token',secret:true}];for(const f of fields)field(panel,f.label,'',v=>values[f.key]=v,{type:f.secret?'password':'text'});const message=E('p','','connection-message');panel.append(B('Save connection',async()=>{try{await api('studio/credentials/'+id,{method:'PUT',body:J(values)});S.credentials=await api('studio/credentials');message.textContent='Saved. Test access or authorize the connection.';canvas();}catch(e){message.textContent=e.message;}},'primary'),B('Test access',async()=>{try{const result=await api('studio/credentials/'+id+'/test',{method:'POST',body:'{}'});message.textContent='Verified · '+clock(result.testedAt);}catch(e){message.textContent=e.message;}},'secondary'));if(['google','microsoft'].includes(id)){const scopes=E('div','','scope-grid'),chosen=new Set([id==='google'?'sheets':'profile']);for(const key of Object.keys(id==='google'?googleScopes:microsoftScopes)){const l=E('label'),c=E('input');c.type='checkbox';c.checked=chosen.has(key);c.onchange=()=>c.checked?chosen.add(key):chosen.delete(key);l.append(c,document.createTextNode(key.replaceAll('_',' ')));scopes.append(l);}panel.append(scopes,B('Connect '+p.name,async()=>{try{if(id==='google'&&S.dirty&&!await save())return;const result=await api('studio/'+id+'/start',{method:'POST',body:J({services:[...chosen]})});if(id==='google')location.assign(result.url);else{message.textContent='Enter '+result.userCode+' on the Microsoft verification page. This page will check authorization.';externalLink(panel,'Open Microsoft verification ↗',result.verificationUri);const poll=async()=>{if(!$('#modal').open)return;try{const v=await api('studio/microsoft/poll',{method:'POST',body:J({id:result.id})});if(v.pending)setTimeout(poll,(v.interval||5)*1000);else{S.credentials=await api('studio/credentials');message.textContent='Microsoft connected.';canvas();}}catch(e){message.textContent=e.message;}};setTimeout(poll,5000);}}catch(e){message.textContent=e.message;}},'secondary'));}panel.append(message);}});}
function addins(){dialog('Integration library',h=>{h.append(E('p','Ready-made blocks use fixed provider endpoints and editable input mappings. Availability depends on API access, app approval and account plan.','muted'));const grid=E('div','','integration-grid');for(const [id,p]of Object.entries(credentialProviders)){const card=E('div','','integration-card');card.append(E('h3',p.name),E('span',S.credentials[id]?'Configured':'Setup required','pill'),E('p',p.cost,'muted'),B('Set up connection',()=>credentials(id),'secondary'));grid.append(card);}h.append(grid,B('Create a custom HTTPS add-in',customAddins,'primary'));});}
function mediaJobs(){dialog('Media jobs',async h=>{h.append(E('p','Cloud generation is asynchronous. Refresh to inspect real status. Provider URLs can expire. Archive completed outputs (up to 64 MB each) to durable storage, or download them directly. No automatic paid retries.','muted'));if(!S.owner)return h.append(E('p','Sign in to inspect your submitted jobs.'));const {jobs}=await api('studio/media');if(!jobs.length)h.append(E('p','No media jobs submitted yet.','muted'));for(const state of jobs){const card=E('div','','list-card');const show=s=>{card.replaceChildren();card.append(E('strong',s.model+' · '+s.status),E('small',s.createdAt),E('p',s.error||'','muted'));for(const url of (Array.isArray(s.output)?s.output:[s.output]).filter(x=>typeof x==='string'&&x.startsWith('https://')))externalLink(card,'Open / download output ↗',url);for(const f of s.files||[])externalLink(card,'Download archived '+f.name,'/api/studio/files/'+f.id);if(s.status==='succeeded'&&!s.files?.length)card.append(B('Archive to Drive',async()=>{try{show(await api('studio/media/'+s.id+'/archive',{method:'POST',body:'{}'}));toast('Media archived and acknowledged by storage.');}catch(e){toast(e.message,true);}},'secondary'));if(s.providerUrl?.startsWith('https://'))externalLink(card,'Provider job ↗',s.providerUrl);externalLink(card,'Model pricing ↗',s.pricingUrl);card.append(B('Delete job',()=>removeSaved('studio/media/'+s.id,'Delete this job record? This does not cancel a provider job or remove archived files and Drive recovery history.',{done:refresh=>{if(refresh)mediaJobs();}}),'secondary danger'));card.append(B('Refresh status',async()=>{try{show(await api('studio/media/'+s.id+'/inspect',{method:'POST',body:'{}'}));}catch(e){toast(e.message,true);}},'secondary'));};show(state);h.append(card);}});}
async function previewWorkflow(){const allowed=['chat','output','function','set','stats','report','condition','note'];if(S.graph.nodes.some(n=>n.enabled!==false&&!allowed.includes(n.type)))return toast('Connect and sign in to run server or cloud blocks. Use the Process JSON template for a free local preview.',true);let input={text:S.chat};try{if(/^\s*[\[{]/.test(S.chat))input=JSON.parse(S.chat);S.running=true;S.runStale=false;S.run={id:uid(),status:'running',trace:[]};render();S.previewController=new AbortController();const result=await executeWorkflow(S.graph,input,{signal:S.previewController.signal,executeFunction:(code,input)=>testFunction(code,input,{signal:S.previewController.signal}),onStep:async trace=>{S.run.trace=structuredClone(trace);canvas();consolePanel();}});S.run={...S.run,...result,status:'success'};toast('Local preview completed. This result is not saved to the server.');}catch(e){S.run={...S.run,status:'error',error:e.message};toast(e.message,true);}finally{S.previewController=null;S.running=false;render();}}

function starter(kind){if(['agents','text'].includes(kind))return template(kind);const kinds={report:['chat','stats','report','output'],content:['chat','content_agent','output'],script:['chat','script_agent','output'],video:['chat','text_to_video','output']},types=kinds[kind]||kinds.report,nodes=types.map((type,i)=>newNode(type,80+i*310,160)),edges=nodes.slice(1).map((n,i)=>({id:uid(),source:nodes[i].id,sourcePort:'out',target:n.id,targetPort:'in'}));if(['content','script'].includes(kind)){const model=newNode('model',390,420);nodes.push(model);edges.push({id:uid(),source:model.id,sourcePort:'model',target:nodes[1].id,targetPort:'model'});}return {schemaVersion:1,nodes,edges};}


function saveLayout(){try{localStorage.setItem('th_studio_layout',J({...panelSizes,pinned:S.inspectorPinned}));}catch{}}
function layout(){const root=$('.studio');root.classList.toggle('canvas-full',S.fullView);root.classList.toggle('inspector-hidden',!S.inspectorPinned&&!S.selected&&!S.edge&&!S.preview);for(const [key,value]of Object.entries(panelSizes))root.style.setProperty('--'+key+'-size',value+'px');const full=$('#tools button[title="Full view / restore panels"]');full?.setAttribute('aria-pressed',String(S.fullView));}
function resetLayout(){Object.assign(panelSizes,{library:240,inspector:310,terminal:235});S.inspectorPinned=true;saveLayout();layout();}
function addResizeHandle(host,key){const handle=E('div','','resize-handle resize-'+key);handle.tabIndex=0;handle.setAttribute('role','separator');handle.setAttribute('aria-label','Resize '+key);handle.setAttribute('aria-orientation',key==='terminal'?'horizontal':'vertical');host.append(handle);const clamp=v=>{const root=$('.studio'),other=key==='library'?'inspector':'library',hidden=root.classList.contains(other==='library'?'library-hidden':'inspector-hidden');const maximum=key==='terminal'?Math.max(120,Math.min(innerHeight-320,innerWidth<=900?innerHeight*.4:Infinity)):Math.max(220,Math.min(600,innerWidth-62-260-(hidden?0:panelSizes[other])));return Math.max(key==='terminal'?120:220,Math.min(v,maximum));};handle.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();e.stopPropagation();const start={x:e.clientX,y:e.clientY,size:panelSizes[key]};handle.setPointerCapture(e.pointerId);document.body.classList.add('resizing');handle.onpointermove=ev=>{const delta=key==='terminal'?start.y-ev.clientY:key==='inspector'?start.x-ev.clientX:ev.clientX-start.x;panelSizes[key]=clamp(start.size+delta);layout();};const finish=()=>{handle.onpointermove=null;document.body.classList.remove('resizing');saveLayout();};handle.onpointerup=finish;handle.onpointercancel=finish;};handle.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const direction=['ArrowRight','ArrowDown'].includes(e.key)?1:-1;panelSizes[key]=clamp(panelSizes[key]+direction*20);layout();saveLayout();};handle.ondblclick=()=>{panelSizes[key]=key==='library'?240:key==='inspector'?310:235;saveLayout();layout();};}
try{const value=JSON.parse(localStorage.getItem('th_studio_layout')||'null');if(value){for(const key of Object.keys(panelSizes))if(Number.isFinite(value[key]))panelSizes[key]=Math.max(key==='terminal'?120:220,Math.min(value[key],key==='terminal'?Math.max(150,innerHeight-320):600));S.inspectorPinned=value.pinned!==false;}}catch{}
addResizeHandle($('.library'),'library');addResizeHandle($('.console'),'terminal');layout();
